<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 0;
    font-family: 'Century Gothic', 'Trebuchet MS', Arial, sans-serif;
    background: linear-gradient(180deg, #2f9fe0 0%, #1a7fc4 50%, #2f9fe0 100%);
    width: 1024px;
    height: 768px;
    position: relative;
    overflow: hidden;
  }

  /* decorative green blobs to approximate background graphic */
  .blob {
    position: absolute;
    background: radial-gradient(circle at 30% 30%, #a4d84a, #6fb92c);
    border-radius: 50%;
    opacity: 0.95;
  }
  .blob.top {
    width: 520px;
    height: 240px;
    top: -120px;
    left: 460px;
    border-radius: 45% 55% 60% 40% / 50% 50% 50% 50%;
  }
  .blob.bottom {
    width: 620px;
    height: 260px;
    bottom: -140px;
    left: 380px;
    border-radius: 55% 45% 40% 60% / 45% 55% 45% 55%;
  }

  .globe {
    position: absolute;
    bottom: 10px;
    right: 15px;
    width: 90px;
    height: 90px;
    border-radius: 50%;
    background: radial-gradient(circle at 40% 35%, #cdeb8f 0%, #6fb92c 60%, #3f7a1a 100%);
    box-shadow: 0 0 0 2px rgba(255,255,255,0.2);
  }

  .slide-panel {
    position: absolute;
    top: 60px;
    left: 35px;
    width: 950px;
    height: 600px;
    background: #f2f2f2;
    border-radius: 6px;
    box-shadow: 0 4px 10px rgba(0,0,0,0.3);
    padding: 30px 45px;
  }

  h1 {
    font-size: 34px;
    font-weight: normal;
    color: #1a1a1a;
    margin: 0 0 25px 0;
  }

  table {
    border-collapse: collapse;
    width: 900px;
    font-size: 17px;
    color: #333;
  }

  thead th {
    background: #f4a11d;
    color: #fff;
    font-weight: normal;
    text-align: center;
    padding: 8px 10px;
    width: 33%;
    font-size: 18px;
  }

  thead th.label-col {
    background: #f2f2f2;
  }

  tbody td {
    padding: 6px 12px;
    vertical-align: middle;
    border-bottom: 1px solid #d9d9d9;
  }

  tbody td.label {
    background: #b3b3b3;
    color: #1a1a1a;
    text-align: left;
    font-size: 17px;
    width: 34%;
  }

  tbody td.val {
    text-align: center;
    background: #ffffff;
    width: 33%;
  }

  tr:last-child td {
    border-bottom: none;
  }

  .footer-text {
    position: absolute;
    bottom: 15px;
    left: 0;
    width: 100%;
    text-align: center;
    color: rgba(255,255,255,0.55);
    font-size: 13px;
    line-height: 1.4;
  }

  .date-text {
    position: absolute;
    bottom: 22px;
    left: 30px;
    color: rgba(255,255,255,0.55);
    font-size: 13px;
  }
</style>
</head>
<body>

  <div class="blob top"></div>
  <div class="blob bottom"></div>

  <div class="slide-panel">
    <h1>LP gas and technical specifications</h1>

    <table>
      <thead>
        <tr>
          <th class="label-col"></th>
          <th>Butane</th>
          <th>Propane</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td class="label">Chemical formula</td>
          <td class="val">C<sub>4</sub>H<sub>10</sub></td>
          <td class="val">C<sub>3</sub>H<sub>8</sub></td>
        </tr>
        <tr>
          <td class="label">Density at 15°C</td>
          <td class="val">Heavier than air</td>
          <td class="val">Heavier than air</td>
        </tr>
        <tr>
          <td class="label">As gas</td>
          <td class="val">2.40 kg/m<sup>3</sup></td>
          <td class="val">1.85 kg/m<sup>3</sup></td>
        </tr>
        <tr>
          <td class="label">As liquide</td>
          <td class="val">0.58 kg/l</td>
          <td class="val">0.51 kg/l</td>
        </tr>
        <tr>
          <td class="label">Boiling point at atmospheric pressure</td>
          <td class="val">-2°C</td>
          <td class="val">-42°C</td>
        </tr>
        <tr>
          <td class="label">Gas pressure at -20°C</td>
          <td class="val">0</td>
          <td class="val">1.5 bar</td>
        </tr>
        <tr>
          <td class="label">Gas pressure at 0°C</td>
          <td class="val">0</td>
          <td class="val">4 bar</td>
        </tr>
        <tr>
          <td class="label">Gas pressure at +20°C</td>
          <td class="val">1.3 bar</td>
          <td class="val">7.5 bar</td>
        </tr>
        <tr>
          <td class="label">Energy content</td>
          <td class="val">49.5 MJ/kg<br>12.6 kWh/kg</td>
          <td class="val">50.4 MJ/kg<br>12.8 kWh/kg</td>
        </tr>
        <tr>
          <td class="label">Amount of air required for combustion</td>
          <td class="val">12.0 m<sup>3</sup>/kg</td>
          <td class="val">12.2 m<sup>3</sup>/kg</td>
        </tr>
        <tr>
          <td class="label">Maximum flame temperature with air</td>
          <td class="val">1925°C</td>
          <td class="val">1925°C</td>
        </tr>
        <tr>
          <td class="label">Combustion mixtures, volume-% gas in air</td>
          <td class="val">1.5 - 8.5%</td>
          <td class="val">2.1 - 9.5%</td>
        </tr>
      </tbody>
    </table>
  </div>

  <div class="globe"></div>

  <div class="date-text">2/5/2024</div>
  <div class="footer-text">
    Prepared by: Engr. Mohammad Imam<br>
